  yield val_x * 3;
}

const iter_g = gen_func();
console.log(iter_g.next().value);
console.log(iter_g.next(10).value);
console.log(iter_g.next().value);

Examine the following PyTorch custom autograd function snippet:

```python
class Func_A(torch.autograd.Function):
    @staticmethod
    def forward(ctx, var_q, var_k):
        ctx.save_for_backward(var_q, var_k)
        return var_q * var_k

    @staticmethod
    def backward(ctx, grad_output):
        var_q, var_k = ctx.saved_tensors
        return grad_output * var_k, None
```

